class Animal {
    protected String name;

    Animal(String name) {
        this.name = name;
    }

    void eat() {
        System.out.println(name + "：……");
    }
}

class Cat extends Animal {
    Cat(String name) {
        super(name);
    }

    @Override
    void eat() {
        System.out.println(name + "：吃小鱼干");
    }
}

class Dog extends Animal {
    Dog(String name) {
        super(name);
    }
}

public class Main {
    public static void main(String[] args) {
        Animal[] pets = { new Cat("小橘"), new Dog("大黄") };
        for (Animal pet : pets) {
            pet.eat();
        }
    }
}
